import { Link } from 'react-router-dom';

import styled from '@emotion/styled';
import { ArrowRight } from 'components/icon';
import { Card, Heading, Paragraph } from 'components/UI';
import { theme } from 'theme';

export const exploreFurtherBasicContainerBackground = '#F9F9F9';

export const StyledExploreFurtherRoot = styled.div<{ dataTestId: string }>(
  ({ dataTestId }) => ({
    width: '100%',
    [`& [data-testid="${dataTestId}-title"]`]: {
      fontSize: '32px !important',
      fontWeight: '600 !important',
    },
    [`& [data-testid="${dataTestId}-tooltip"]  div`]: {
      width: '24px',
    },
  }),
);

export const StyledExploreFurtherBody = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  width: '100%',
  padding: '0 24px 24px',
});

export const StyledExploreFurtherCards = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
  gridAutoFlow: 'row',
  alignItems: 'stretch',
  gap: '16px',
  width: '100%',
  minWidth: 0,
  isolation: 'isolate',

  '@media (min-width: 1440px)': {
    gap: '24px',
  },
});

const commercialResultsOuterShell = {
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  maxWidth: '100%',
  minWidth: 0,
  height: '100%',
  alignSelf: 'stretch',
  color: 'inherit',
} as const;

export const StyledCardHeaderRow = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'flex-start',
  gap: '16px',
  width: '100%',
});

interface StyledCardIconProps {
  $tone?: 'active' | 'muted';
}

export const StyledCardIcon = styled('span')<StyledCardIconProps>(
  ({ $tone = 'active' }) => ({
    flexShrink: 0,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: '64px',
    minHeight: '64px',
    borderRadius: '50%',
    fontFamily: theme.fonts.heading,
    fontSize: '20px',
    fontWeight: 700,
    letterSpacing: '-0.02em',
    lineHeight: 1,
    ...($tone === 'active' && {
      backgroundColor: '#141414A3',
      color: '#FFFFFF',
    }),
    ...($tone === 'muted' && {
      backgroundColor: '#14141429',
      color: '#8F8F8F',
    }),
  }),
);

export const StyledCardTextColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  flex: 1,
  minWidth: 0,
});

interface StyledCardTitleProps {
  $muted?: boolean;
}

export const StyledCardTitle = styled(Heading, {
  shouldForwardProp: (prop) => prop !== '$muted',
})<StyledCardTitleProps>(({ $muted }) => ({
  fontSize: '20px !important',
  lineHeight: '20px !important',
  margin: 0,
  fontWeight: 'bold',
  color: '#141414 !important',
  ...($muted && {
    color: '#14141452 !important',
  }),
}));

interface StyledCardDescriptionProps {
  $muted?: boolean;
}

export const StyledCardDescription = styled(Paragraph, {
  shouldForwardProp: (prop) => prop !== '$muted',
})<StyledCardDescriptionProps>(({ $muted }) => ({
  fontSize: '16px !important',
  lineHeight: '24px !important',
  color: '#1414148f !important',
  margin: 0,
  ...($muted && {
    color: '#14141452 !important',
  }),
}));

export const StyledCardFooter = styled.div({
  display: 'flex',
  justifyContent: 'flex-end',
  marginTop: 'auto',
  paddingTop: '24px',
  width: '100%',
  alignSelf: 'stretch',
  boxSizing: 'border-box',
});

interface StyledCardLinkLabelProps {
  $muted?: boolean;
}

export const StyledCardLinkLabel = styled(Paragraph, {
  shouldForwardProp: (prop) => prop !== '$muted',
})<StyledCardLinkLabelProps>(({ $muted }) => ({
  fontSize: '16px !important',
  lineHeight: '20px !important',
  fontWeight: '600',
  margin: 0,
  color: '#141414',
  ...($muted && {
    color: '#BDBDBD',
  }),
}));

interface StyledCommercialResultsLinkLabelProps {
  $disabled?: boolean;
  $muted?: boolean;
}

export const StyledCommercialResultsLinkLabel = styled(StyledCardLinkLabel, {
  shouldForwardProp: (prop) => prop !== '$disabled' && prop !== '$muted',
})<StyledCommercialResultsLinkLabelProps>(({ $disabled }) => ({
  display: 'inline-flex',
  alignItems: 'center',
  gap: '8px',
  color: '#554934 !important',
  ...($disabled && {
    color: '#0000005C !important',
  }),
}));

export const StyledExploreFurtherLinkArrow = styled(ArrowRight)({
  flexShrink: 0,
  color: 'inherit',
  '& svg': {
    width: '16px',
    height: '16px',
  },
});

const exploreFurtherCardBase = {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  width: '100%',
  maxWidth: '100%',
  minWidth: 0,
  height: '100%',
  boxSizing: 'border-box',
  minHeight: '176px',
  padding: '24px',
  backgroundColor: '#FFFFFF',

  '@media (min-width: 1440px)': {
    minHeight: '192px',
  },
} as const;

interface StyledCommercialResultsCardProps {
  $interactive?: boolean;
}

export const StyledCommercialResultsCard = styled(Card, {
  shouldForwardProp: (prop) => prop !== '$interactive',
})<StyledCommercialResultsCardProps>(({ $interactive = true }) => ({
  ...exploreFurtherCardBase,
  flex: 'none',
  ...($interactive && {
    cursor: 'pointer',
    pointerEvents: 'auto',
    backgroundColor: '#FFFFFF',
    boxShadow: '0 0 0 0.0625rem #1414141F !important',
  }),
  ...($interactive === false && {
    cursor: 'default',
    pointerEvents: 'none',
    backgroundColor: '#FAFAFA',
    boxShadow: '0 0 0 0.0625rem #14141414 !important',
  }),
}));

export const StyledWatchTowerBody = styled.div({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'flex-start',
  width: '100%',
  height: '100%',
  flex: 1,
  minHeight: 0,
});

interface StyledCommercialResultsLinkProps {
  $interactive?: boolean;
}

export const StyledCommercialResultsLink = styled(Link, {
  shouldForwardProp: (prop) => prop !== '$interactive',
})<StyledCommercialResultsLinkProps>(({ $interactive }) => ({
  ...commercialResultsOuterShell,
  textDecoration: 'none',
  ...($interactive && {
    cursor: 'pointer',
    pointerEvents: 'auto',
  }),
  ...($interactive === false && {
    cursor: 'default',
    pointerEvents: 'none',
  }),
}));
